---- LOOK AND FEEL ----
-----------------------

-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
hl.config({
    general = {
        gaps_in  = 8,
        gaps_out = 10,

        border_size = 2,

        col = {
   		 active_border   = { colors = { colors.accent, colors.bg_button }, angle = 45 },
   		 inactive_border = colors.bg_inactive,
	},

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    decoration = {
        rounding       = 20,
        rounding_power = 2,

        -- Change transparency of focused and unfocused windows
        active_opacity   = 0.91,
        inactive_opacity = 0.60,

        shadow = {
    		enabled      = true,
    		range        = 4,
    		render_power = 3,
   		color        = colors.shadow,
	},

        blur = {
            enabled   = true,
            size      = 6,
            passes    = 2,
            vibrancy  = 0.1696,
        },
    },

    animations = {
        enabled = true,
    },
})

-- The Curves
hl.curve("bouncy", { type = "bezier", points = { {0.05, 0.9}, {0.1, 1.1} } })
hl.curve("snappy", { type = "bezier", points = { {0.4, 0.0}, {1, 1} } }) 
hl.curve("linear", { type = "bezier", points = { {0, 0}, {1, 1} } })

-- Apply the animations
hl.animation({ leaf = "windows",       enabled = true, speed = 5, bezier = "bouncy", style = "slide" })

-- Changed 'popin' to 'slide' and adjusted speed so it glides away cleanly!
hl.animation({ leaf = "windowsOut",    enabled = true, speed = 2.5, bezier = "snappy", style = "slide" }) 
hl.animation({ leaf = "layersIn",      enabled = true, speed = 5, bezier = "bouncy" })
hl.animation({ leaf = "layersOut",     enabled = true, speed = 2.5, bezier = "snappy" })

hl.animation({ leaf = "border",        enabled = true, speed = 5, bezier = "bouncy" })
hl.animation({ leaf = "fade",          enabled = true, speed = 2, bezier = "linear" })
hl.animation({ leaf = "workspaces",    enabled = true, speed = 6, bezier = "bouncy", style = "slide" })
hl.animation({ leaf = "specialWorkspace", enabled = true, speed = 5, bezier = "bouncy", style = "slidevert" })

