---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/Configuring/Basics/Binds/ for more
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd(terminal))
local closeWindowBind = hl.bind(mainMod .. " + W", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + F", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + V", hl.dsp.layout("togglesplit"))    -- dwindle only

-- Open Program Launcher
hl.bind(mainMod .. " + SPACE", hl.dsp.exec_cmd("pkill wofi || wofi --show drun"))

-- 144Hz Marshmellow Power Menu
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("~/.config/hypr/power-menu.py"))

-- Open Horizontal Wallpaper Carousel
hl.bind(mainMod .. " + SHIFT + W", hl.dsp.exec_cmd("~/.config/hypr/wallpaper-carousel.py"))

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + h",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + l", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + k",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + j",  hl.dsp.focus({ direction = "down" }))

-- Move windows with mainMod + SHIFT + hjkl
hl.bind(mainMod .. " + SHIFT + h", hl.dsp.window.move({ direction = "left" }))
hl.bind(mainMod .. " + SHIFT + j", hl.dsp.window.move({ direction = "down" }))
hl.bind(mainMod .. " + SHIFT + k", hl.dsp.window.move({ direction = "up" }))
hl.bind(mainMod .. " + SHIFT + l", hl.dsp.window.move({ direction = "right" }))

-- Screenshots (LumineCapture)
hl.bind(mainMod .. " + P",         hl.dsp.exec_cmd("lumine-capture -m")) -- Capture active monitor
hl.bind(mainMod .. " + SHIFT + P", hl.dsp.exec_cmd("lumine-capture"))    -- Resizable selection / Editor
hl.bind(mainMod .. " + CTRL + P",  hl.dsp.exec_cmd("lumine-capture -f")) -- Capture all monitors (fullscreen)

-- Reload Waybar
hl.bind(mainMod .. " + SHIFT + B", hl.dsp.exec_cmd("killall waybar; waybar"))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness (SwayOSD)
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("sh -c 'swayosd-client --output-volume raise'"))
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("sh -c 'swayosd-client --output-volume lower'"))
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("sh -c 'swayosd-client --output-volume mute-toggle'"))
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("swayosd-client --input-volume mute-toggle"), { locked = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("swayosd-client --brightness raise"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("swayosd-client --brightness lower"), { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/



-- Float and center the GTK4 Marshmellow Help Guide Card
hl.window_rule({
    name  = "float-help-guide",
    match = { title = "^Hyprland Keybinds$" },

    float   = true,
    center  = true,
    opacity = "0.95 override 0.85 override",
})

-- Pin the Audio Dropdown right below Waybar in the top-right corner
hl.window_rule({
    name  = "audio-dropdown-menu",
    match = { title = "^Audio Control$" },

    float = true,
    opacity     = "0.95 override 0.5 override",
    move  = { "monitor_w-window_w-15", "46" },
    animation = "slide top",
})
-- Pin the Clipboard Dropdown right below Waybar, strictly inside the active monitor
hl.window_rule({
    name  = "clipboard-dropdown-menu",
    match = { title = "^Clipboard History$" },

    float = true,
    opacity     = "0.95 override 0.5 override",
    move  = { "monitor_w-window_w-15", "46" },
    animation = "slide top",
})

-- Make LumineCapture open as a borderless fullscreen overlay instead of tiling
hl.window_rule({
    name  = "lumine-capture-overlay",
    match = { class = "^(.*[Ll]umine.*)$" },

    float       = true,
    fullscreen  = true,
    border_size = 0,
    rounding    = 0,
    no_anim     = true,
    opacity     = "1.0 override 1.0 override",
})

-- Pin the Media Dropdown to the top center
hl.window_rule({
    name  = "media-dropdown-menu",
    match = { title = "^Media Control$" },

    float     = true,
    move      = { "monitor_w/2 - window_w/2", "46" },
    opacity   = "0.95 override 0.50 override",
    animation = "slide top",
})

-- Picture-in-Picture (PiP) Rules
hl.window_rule({
    name  = "picture-in-picture",
    match = { title = "^Picture-in-Picture$" },

    float   = true,
    pin     = true,
    move    = { "monitor_w - window_w - 20", "monitor_h - window_h - 20" },
    opacity = "1.0 override 1.0 override",
})

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})

-- Keep Terminal text 100% opaque (Kitty handles its own background transparency!)
hl.window_rule({
    name  = "opaque-terminal-text",
    match = { class = "^(kitty|hypr-help)$" },

               opacity = "1.0 override 0.6 override",
})

hl.window_rule({
    name = "opaque-neo",
    match = { class = "neo" },
    opacity = "1.0 override 1.0 override"
})

-- 100% Opacity on Focused Video Tabs & Media Players (60% when unfocused)
hl.window_rule({
    name  = "opaque-focused-videos",
    match = { title = ".*(YouTube|Twitch|Netflix|Crunchyroll|Prime Video|Disney\\+|Plex|mpv|VLC).*" },

               opacity = "1.0 override 0.6 override",
})

-- 100% Opacity for CoverBuilder when focused (60% when unfocused)
hl.window_rule({
    name  = "opaque-coverbuilder",
    match = { class = ".*[Cc]over[Bb]uilder.*" },

    opacity = "1.0 override 0.6 override",
})

-- Float & Center the 144Hz Power Menu
hl.window_rule({
    name  = "marshmellow-power-menu",
    match = { title = "^Marshmellow Power Menu$" },

    float   = true,
    center  = true,
    opacity = "1.0 override 1.0 override",
})

-- Always 100% Opacity on Any Fullscreen Window / Video
hl.window_rule({
    name  = "opaque-fullscreen",
    match = { fullscreen = true },

    opacity = "1.0 override 1.0 override",
})

-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- Float and center Marshmellow Studio
hl.window_rule({
    name  = "float-marshmellow-studio",
    match = { title = "^Marshmellow Studio$" },

    float   = true,
    center  = true,
    opacity = "0.95 override 0.90 override",
})

-- Transparent 144Hz Diamond Wave Wallpaper Switcher
hl.window_rule({
    name  = "marshmellow-wallpaper-carousel",
    match = { title = "^Marshmellow Wallpapers$" },

    float       = true,
    size        = "1800 480",
    center      = true,
    border_size = 0,
    no_blur     = true,
    no_shadow   = true,
    opacity     = "1.0 override 1.0 override",
})

-- Make SwayNC slide down from the top and enable frosted glass blur
hl.layer_rule({
    name  = "swaync-dropdown-anim",
    match = { namespace = "^swaync-control-center$" },

    animation   = "slide top",
    blur        = true,
})

-- Bind Workspace 2 permanently to the vertical monitor (DP-3)
hl.workspace_rule({
    workspace = "2",
    monitor   = "DP-3",
    default   = true,
})

-- Always open the vertical dashboard apps on Workspace 2 (DP-3)
hl.window_rule({
    name      = "vertical-dashboard-ws2",
    match     = { class = "^marshmellow-(btop|lava|cava)$" },
    workspace = "2",
    opacity   = "1.0 override 0.6 override",
})

-- Autostart vertical monitor dashboard (btop on top, lavat + cava on bottom)
hl.on("hyprland.start", function()
    hl.exec_cmd("~/.config/hypr/vertical-dashboard.sh")
end)
